function this.LUA_TRIGGER_DROP_ITEM_NAME_CHANGE(_,item)
    local cfg = SL:GetConfig("cfg_item", item.cfgId)
    if cfg then
        local type = cfg.type
        local subType = cfg.subType
        local name = cfg.name
        local space = "*"
        if name == "金币" then
            name = "金"
            space = " "
        end

        if this.showcountItemType[type] then
            if next(this.showcountItemType[type]) == nil then
                return name..space..item.count
            else
                if this.showcountItemType[type][subType] then
                    return name..space..item.count
                end
            end
        end
    end
end

