function this.LUA_TRIGGER_SET_STREAM(_,go, roleId,itemCfgId,strengthLevel)
    if not SL:HasConfig('cfg_equip_strengthen',itemCfgId) then
        return
    end
    if not this.tempEqupInfo then
        this.tempEqupInfo = {}
    end
    this.tempEqupInfo.cfgId = itemCfgId
    local liuGuangId = EquipFunc.GetEquipLiuGuangId(this.tempEqupInfo,strengthLevel)
    if liuGuangId then
        SL:SetMetaValue(EMetaVarSetKey.EQUIP_STREAMER_REFRESH,go,liuGuangId)
    end
end

--进入地图 预显示界面
function this.LUA_EVENT_ENTER_MAP(_, eventData)
    local isChangeMap = eventData
    GUI:UIPanel_Open("dev/outui/ExpMessage/Panel/KLUIExpMessage/KLUIExpMessagePanel")
    GUI:UIPanel_Open("dev/outui/Message/Panel/KLHorseRaceLamp/KLHorseRaceLampPanel")
    GUI:UIPanel_Open("dev/outui/Activity/Panel/KLActivityPreview/KLActivityPreviewPanel")
    if not GUI:IsWebGLAsync() then
        Coroutine.Start(function()
            --预打开一下
            if not isChangeMap then
                Coroutine.WaitForEndOfFrame()
                GUI:UIPanel_Open("dev/ui/Equip/Panel/KLEquipUI/KLEquipUIPanel", nil, nil, { x = -400, y = 0, relatePanel = "",isPreLoad = true })
                GUI:UIPanel_Close("dev/ui/Equip/Panel/KLEquipUI/KLEquipUIPanel")
            end
        end) 
    end

    GUI:UIPanel_Open("dev/ui/Common/Panel/KLTop/KLTopPanel")
    --this.PreLoad()
    this.ClearCopyData()
    InfoManager.copActivityInfo:ClearCopyData()
    SL:SetOffset2CSPreScene(Vector3(0, 0, 0))
    SL:UpdateMainCameraPos()

    if firstRun then
        firstRun = false
        local cameraDistance = tonumber(SL:GetLocalString("GET_CAMERA_DISTANCE"))
        if cameraDistance and cameraDistance > 0 then
            if cameraDistance == 13 then
                SL.MainCamera:SetLookCamera(true,Vector2(32,-45),10,10,90)
            else
                --设置相机距离
                if SL:GetMetaValue(EMetaVarGetKey.ENGINE_IS_LOCK_CAMERA) then
                    SL.MainCamera:SetLookCamera(false,Vector2(32,-45),10,10,90)
                end
                SL.MainCamera:Set3DCameraParams(cameraDistance,45,45)
            end
        end
    end
    --SL:BanAutoFinishNpcTalkTask()
end

