function this.PreLoad(...)
    if this.isHasPreLoad then
        return  
    end
    this.isHasPreLoad = true
    if not GUI:IsWebGLAsync() then
        local co = Coroutine.Start(function()
            --Coroutine.WaitForEndOfFrame()
            --GUI:PreLoadUI("dev/ui/Equip/Panel/KLEquipUI/KLEquipUIPanel", 1)
            Coroutine.WaitForEndOfFrame()
            GUI:PreLoadUI("dev/ui/Bag/Panel/KLUIBag/KLUIBagPanel", 1)
            --Coroutine.WaitForEndOfFrame()
            --GUI:PreLoadUI("dev/ui/Common/Item/KLBagItem/KLBagItemItem",50)
        end
        ) 
    end
    
end

