--职业改变
function this.LUA_EVENT_CAREER_CHANGED(_, data)
    local preCareer = data.currentCareer
    local nextCareer = data.newCareer
    ---@type cfg_career_column
    local careerConfig = SL:GetConfig("cfg_career", nextCareer)
    if careerConfig.window == 1 then
        GUI:UIPanel_Open("dev/outui/Career/Panel/KLCareerChangePanel/KLCareerChangePanel", nil, nil, { currentCareer = nextCareer, originalCareer = preCareer })
    end
end

function this.RES_ROLE_ATT_ADD_WAY(_,data)
    local addWay = data
    SL:MeData_GetRoleExtInfo().attAddWay = addWay
    SL:onLUAEvent(LUA_EVENT_SURE_ATTR_PLAN, data)
end

function this.RES_IN_OUT_CROSS_MAP(id, message)
    local mapId = SL:GetMetaValue(EMetaVarGetKey.MAP_ID)
    if mapId == ECrossServerActivityMapId.QuintonInvasion then
        this.isCrossServer = 0
        return
    end
    this.isCrossServer = message.type
    if this.isCrossServer and this.isCrossServer == 1 then
        if not SL:MeData_GetUnionId() or SL:MeData_GetUnionId() == 0 then
            SL:SetMetaValue(EMetaVarSetKey.SET_PKMODE, 0)
            SL:onLUAEvent(LUA_EVENT_CROSS_SERVER_PK_MODE,0)
        else
            SL:SetMetaValue(EMetaVarSetKey.SET_PKMODE, 5)
            SL:onLUAEvent(LUA_EVENT_CROSS_SERVER_PK_MODE,5)
        end
    end
    
end

function this.ResViewUnionMessage(id, message)
    if message.unionInfo and message.unionInfo.unionId then
        if this.isCrossServer and this.isCrossServer == 1 then
            if not SL:MeData_GetUnionId() or SL:MeData_GetUnionId() == 0 then
                SL:SetMetaValue(EMetaVarSetKey.SET_PKMODE, 0)
                SL:onLUAEvent(LUA_EVENT_CROSS_SERVER_PK_MODE,0)
            else
                SL:SetMetaValue(EMetaVarSetKey.SET_PKMODE, 5)
                SL:onLUAEvent(LUA_EVENT_CROSS_SERVER_PK_MODE,5)
            end
        end
    end
end

function this.ResQuitUnionMessage(id, message)
    if message.isQuit then
        if this.isCrossServer and this.isCrossServer == 1 then
            SL:SetMetaValue(EMetaVarSetKey.SET_PKMODE, 0)
            SL:onLUAEvent(LUA_EVENT_CROSS_SERVER_PK_MODE,0)
        end
    end
end

function this.LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER(id, message)
    this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER = message
    
    local map_line = SL:GetMetaValue(EMetaVarGetKey.MAP_LINE)
    local map_id = SL:GetMetaValue(EMetaVarGetKey.MAP_ID)
    if SL:GetIsWebGL() then
        if map_id == message.mapCfgId and message.line == map_line and SL:MeData_Check() then
            GUI:UIPanel_Close("dev/outui/ChallengeBoss/Panel/KLChallengeBoss/KLChallengeBossPanel")
            SL.ShowMainPanel()
            this.check_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER()
        end
    end
end

function this.check_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER(message)
    if not this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER then
        return
    end
    if not SL:GetIsWebGL() then
        SL:ScheduleOnce(0.3, function()
            this.start_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER(message)
        end)
    else
        SL:ScheduleOnce(0.3, function()
            this.CheckPos()
        end)
    end
end

