function this.CheckPos()
    if not this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER then
        return
    end
    local message = this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER
    this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER = nil
    local map_id = SL:GetMetaValue(EMetaVarGetKey.MAP_ID)
    local map_line = SL:GetMetaValue(EMetaVarGetKey.MAP_LINE)
    if message.mapCfgId ~= map_id or message.line ~= map_line then
        return
    end
    local me_x = SL:MeData_GetCoord().x
    local me_y = SL:MeData_GetCoord().z
    local all_status = SL:GetMapMonsterStatus()
    local one = 1
    local min_distance = nil
    local min_data = nil
    for i, data in ipairs(all_status) do
        if data.configId == message.monsterCfgId and data.status == one then
            --table.insert(all_monster,{configId=data.configId,x=data.pointX,y=data.pointY})
            if not min_distance then
                min_data = data
                min_distance = SL:GetPointDistance({x=me_x,z=me_y},{x=data.pointX,z=data.pointY})
            else
                local distance = SL:GetPointDistance({x=me_x,z=me_y},{x=data.pointX,z=data.pointY})
                if distance < min_distance then
                    min_data = data
                    min_distance =distance
                end
            end
        end
    end
    if min_distance and min_data then
        SL:StopOnHook(true)
        this.pos_monster_id = message.monsterCfgId
        this.map_data = {message.mapCfgId, message.line, min_data.pointX, min_data.pointY}
        SL:Pathfinding(message.mapCfgId, message.line, min_data.pointX, min_data.pointY,this.MonserPosEnd,this.pos_monster_id)
    end
end

function this.start_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER(message)
    if not this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER then
        return
    end
    local message = this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER
    this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER = nil
    local map_id = SL:GetMetaValue(EMetaVarGetKey.MAP_ID)
    local map_line = SL:GetMetaValue(EMetaVarGetKey.MAP_LINE)
    if message.mapCfgId ~= map_id or message.line ~= map_line then
        return
    end
    local me_x = SL:MeData_GetCoord().x
    local me_y = SL:MeData_GetCoord().z
    local all_monster = {}
    local all_status = SL:GetMapMonsterStatus()
    local one = 1
    for i, data in ipairs(all_status) do
        if data.configId == message.monsterCfgId and data.status == one then
            table.insert(all_monster,{configId=data.configId,x=data.pointX,y=data.pointY})
        end
    end
    
    local num = 0
    local index = 0
    --SL:OpenWaitingUI({ msg = "寻怪中"})
    local current_index = 1
    local is_end = false
    this.wait = SL:Schedule(this.wait,0,Time.deltaTime,-1, function()
        if is_end then
            return
        end
        local current_time = Time.GetServerTime() 
            if current_index <= #all_monster then
                local data = all_monster[current_index]
                local arrive, path = SL:SearchPath({x=me_x,z=me_y}, {x=data.x,z=data.y})
                if arrive then
                    data.num = path.n
                    if num == 0 then
                        num = data.num
                        index = current_index
                    else
                        if num > data.num then
                            num = data.num
                            index = current_index
                        end
                    end
                end
                if current_index <= #all_monster then
                    current_index = current_index+1
                    return
                end
            end
        if index > 0 then
            local pos_data = all_monster[index]
            SL:StopOnHook(true)
            this.pos_monster_id = message.monsterCfgId
            this.map_data = {message.mapCfgId, message.line, pos_data.x, pos_data.y}
            SL:Pathfinding(message.mapCfgId, message.line, pos_data.x, pos_data.y,this.MonserPosEnd,this.pos_monster_id)
            --SL:HideWaitingUI()
            SL:UnSchedule(this.wait)
        end
    end)


    
end

function this.LUA_EVENT_PLAYER_ENTER_MAP(id, message)
    this.check_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER(message)
    
end


function this.MonserPosEnd(pos)
    if pos and pos.x and pos.z then
        this.scheduleId = SL:ScheduleOnce(0.1, function()
            SL:Pathfinding( this.map_data[1],  this.map_data[2], pos.x, pos.z,this.BossPointOnHook)
        end)
    else
        SL:StartOnHook(true,true,this.pos_monster_id)
    end
end


function this.BossPointOnHook()
    this.data_LUA_EVENT_CHALLENGE_BOSS_MONSTER_POS_AFTER = nil
    SL:StartOnHook(true,true,this.pos_monster_id)
end

