function this.RES_TASK_STATES_TO_FUNC_ON_MESSAGE(_,message)
    if message then
        SL:ClearSystemFunctionState()
        local tempData = {}
        ---@type cfg_career_column
        local careerTbl = SL:GetMetaValue(EMetaVarGetKey.ME_CAREER_TAB_COLUMN)
        if careerTbl then
            for i, v in pairs(message) do
                local taskId = tonumber(i)
                local taskState = tonumber(v)
                ---@type cfg_system_switch_column[]
                --local tblList = cfg_system_switch_post.GetSystemBtnGetTaskInfo(careerTbl.id,taskId)
                local tblList = SL:CfgSystemSwitchPost_GetSystemBtnGetTaskInfo(careerTbl.id,taskId)
                if tblList then
                    for j, k in pairs(tblList) do
                        SL:SetMetaValue(EMetaVarSetKey.SET_SYSTEM_FUNCTION_TASK_STATE,k.systemName,taskState == TaskState.Accepted)
                        tempData[k.btnPath] = k.btnPath
                    end
                end

                ---@type cfg_system_switch_column[]
                --tblList = cfg_system_switch_post.GetSystemBtnFinishedTaskInfo(careerTbl.id,taskId)
                tblList = SL:CfgSystemSwitchPost_GetSystemBtnGetTaskInfo(careerTbl.id,taskId)
                if tblList then
                    for j, k in pairs(tblList) do
                        SL:SetMetaValue(EMetaVarSetKey.SET_SYSTEM_FUNCTION_TASK_STATE,k.systemName,SL:GetMetaValue(EMetaVarGetKey.GET_SYSTEM_FUNCTION_TASK_STATE,k.systemName) and true or taskState == TaskState.Completed)
                        tempData[k.systemName] = k.btnPath
                    end
                end
            end
        end
        for systemName, btnPath in pairs(tempData) do
            local isShow = SL:GetMetaValue(EMetaVarGetKey.IS_OPEN_SYSTEMFUNCTION, systemName)
            SL:ControlSystemPortalVisible(btnPath, isShow)
        end
    end
end 